class Solution {
  public int countRatioSubarrays(int[] nums, int a, int b) {
    int n = nums.length, count = 0;
    for (int l = 0; l < n; l++) {
      int even = 0, odd = 0;
      for (int r = l; r < n; r++) {
        if (nums[r] % 2 == 0) even++;
        else odd++;
        if (odd > 0 && (long) even * b <= (long) a * odd) count++;
      }
    }
    return count;
  }
}
